void alert_evaluator::evaluate(double now, const json::array_t &metrics, const json::array_t &interfaces) {
	auto evaluate_entries = [this, now](const json::array_t &entries, bool is_interface) {
		for(const auto &entry : entries) {
			const binding *selected = nullptr;
			for(const auto &candidate : m_bindings) {
				if(!matches_binding(candidate, entry, is_interface)) continue;
				if(selected == nullptr || candidate.scope_priority > selected->scope_priority || (candidate.scope_priority == selected->scope_priority && candidate.id < selected->id)) selected = &candidate;
			}
			if(selected == nullptr || selected->disabled) continue;
			for(const auto &r : selected->rules) {
				if(r.enabled && matches_target(r, entry, is_interface)) evaluate_entry(now, r, entry, is_interface);
			}
		}
	};
	evaluate_entries(metrics, false);
	evaluate_entries(interfaces, true);
}

json::array_t alert_evaluator::active_alerts() const {
	json::array_t out;
	for(const auto &[state_key, s] : m_states) {
		if(!s.active) {
			continue;
		}
		json entry = s.source.is_object() ? s.source : json::object();
		if(s.detail.is_object()) {
			for(const auto &[key, value] : s.detail.items()) {
				if(!entry.contains(key)) {
					entry[key] = value;
				}
			}
		}
		entry["state_key"] = state_key;
		entry["state"] = "active";
		entry["last_value"] = s.last_value;
		entry["last_error_time"] = s.last_error_time;
		entry["last_seen_time"] = s.last_seen_time;
		out.push_back(std::move(entry));
	}
	return out;
}

void alert_evaluator::evaluate_entry(double now, const rule &r, const json &entry, bool is_interface) {
	if(!matches_target(r, entry, is_interface)) return;

	const auto state_key = make_state_key(r, entry, is_interface);
	auto &s = m_states[state_key];
	if(r.type == rule_type::availability) {
		evaluate_availability(now, r, entry, is_interface, state_key, s);
		return;
	}
	auto value = metric_value(entry, r.metric);
	const bool available = value.has_value() && std::isfinite(*value);
	update_metric_availability(now, r, entry, is_interface, state_key, s, available);
	if(!available) return;

	s.last_seen_time = now;
	s.metric_available = true;
	s.metric_missing = false;
	switch(r.type) {
	case rule_type::threshold:
		evaluate_threshold(now, r, entry, is_interface, state_key, s, *value);
		break;
	case rule_type::counter_delta:
		evaluate_counter_delta(now, r, entry, is_interface, state_key, s, *value);
		break;
	case rule_type::availability:
		break;
	}
}

void alert_evaluator::evaluate_availability(double now, const rule &r, const json &entry, bool is_interface, const std::string &state_key, state &s) {
	const auto last_seen = metric_value(entry, "last_seen");
	if(!last_seen.has_value() || !std::isfinite(*last_seen)) return;
	const bool inactive = now - *last_seen >= r.inactive_after_sec;
	if(inactive) {
		if(s.active) return;
		s.active = true;
		s.last_error_time = now;
		s.last_seen_time = *last_seen;
		s.source = make_target_source(r, entry, is_interface);
		s.detail = json{{"alert_id", r.id}, {"severity", r.severity}, {"indicator_category", r.indicator_category}, {"metric", r.metric}, {"type", "availability"}, {"inactive_after_sec", r.inactive_after_sec}, {"last_seen", *last_seen}, {"outage_seconds", now - *last_seen}};
		emit_availability_alert(now, r, entry, is_interface, state_key, false, *last_seen);
		return;
	}
	if(s.active) {
		s.active = false;
		emit_availability_alert(now, r, entry, is_interface, state_key, true, *last_seen);
	}
	s.last_seen_time = *last_seen;
	s.source = make_target_source(r, entry, is_interface);
}

void alert_evaluator::update_metric_availability(double now, const rule &r, const json &entry, bool is_interface, const std::string &state_key, state &s, bool available) {
	if(available) {
		if(s.metric_missing) emit_data_availability(now, r, entry, is_interface, state_key, true);
		s.metric_available = true;
		s.metric_missing = false;
		return;
	}
	if(!s.metric_available || r.missing_after_sec <= 0.0 || s.metric_missing || now - s.last_seen_time < r.missing_after_sec) return;
	s.metric_missing = true;
	emit_data_availability(now, r, entry, is_interface, state_key, false);
}

void alert_evaluator::evaluate_threshold(double now, const rule &r, const json &entry, bool is_interface, const std::string &, state &s, double value) {
	if(!s.active) {
		if(!compare(value, r.op, r.error_threshold)) {
			s.error_pending_since = 0.0;
			return;
		}
		if(s.error_pending_since <= 0.0) s.error_pending_since = now;
		if(now - s.error_pending_since < r.trigger_after_sec) return;
		s.active = true;
		s.error_pending_since = 0.0;
		s.recovery_pending_since = 0.0;
		s.last_error_time = now;
		json detail{{"metric", r.metric}, {"value", value}, {"threshold", r.error_threshold}, {"operator", "error"}};
		update_active_state(now, r, entry, is_interface, s, value, detail);
		emit_alert(now, r, entry, is_interface, "detected", value, std::move(detail));
		return;
	}

	if(compare(value, r.op, r.recover_threshold)) {
		s.recovery_pending_since = 0.0;
		update_active_state(now, r, entry, is_interface, s, value, json{{"metric", r.metric}, {"value", value}, {"threshold", r.error_threshold}, {"operator", "error"}});
		return;
	}
	if(s.recovery_pending_since <= 0.0) s.recovery_pending_since = now;
	if(now - s.recovery_pending_since < r.recover_after_sec) return;
	s.active = false;
	s.recovery_pending_since = 0.0;
	emit_alert(now, r, entry, is_interface, "recovered", value, json{{"metric", r.metric}, {"value", value}, {"threshold", r.recover_threshold}, {"operator", "recover"}});
}

void alert_evaluator::evaluate_counter_delta(double now, const rule &r, const json &entry, bool is_interface, const std::string &, state &s, double value) {
	if(!s.has_last_value) { s.has_last_value = true; s.last_value = value; return; }
	const double delta = value - s.last_value;
	s.last_value = value;
	if(compare(delta, r.op, r.delta_threshold)) {
		json detail{{"metric", r.metric}, {"value", value}, {"delta", delta}, {"threshold", r.delta_threshold}};
		if(!s.active) { s.active = true; emit_alert(now, r, entry, is_interface, "detected", value, detail); }
		s.last_error_time = now;
		update_active_state(now, r, entry, is_interface, s, value, std::move(detail));
	case compare_op::eq: return "==";
	case compare_op::ne: return "!=";
	}
	return "?";
}

bool alert_evaluator::matches_binding(const binding &b, const json &entry, bool is_interface) {
	if(!b.monitoring_target_id.empty()) {
		if(is_interface || !entry.contains("monitoring_target_ids") || !entry["monitoring_target_ids"].is_array()) return false;
		return std::any_of(entry["monitoring_target_ids"].begin(), entry["monitoring_target_ids"].end(), [&b](const json &id) {
			return id.is_string() && id.get<std::string>() == b.monitoring_target_id;
		});
	}
	if(b.scope_target == "interface") return is_interface;
	if(is_interface) return b.scope_target == "any";
	if(b.scope_target == "flow" && !entry.contains("flow_key")) return false;
	if(b.scope_target == "stream" && entry.contains("flow_key")) return false;
	if(!b.scope_proto.empty() && json_string_or_empty(entry, "proto") != b.scope_proto) return false;
	return true;
}

bool alert_evaluator::matches_target(const rule &r, const json &entry, bool is_interface) {
	if(r.target == "interface") {
		return is_interface;
	}
	if(is_interface) {
		return r.target == "any";
	}
	if(r.target == "flow" && !entry.contains("flow_key")) {
		return false;
	}
	if(r.target == "stream" && entry.contains("flow_key")) {
		return false;
	}
	if(!r.proto.empty()) {
		const auto proto = json_string_or_empty(entry, "proto");
		if(proto != r.proto) {
			return false;
		}
	}
	if(!r.flow_roles.empty()) {
		const auto role = json_string_or_empty(entry, "role");
		if(std::find(r.flow_roles.begin(), r.flow_roles.end(), role) == r.flow_roles.end()) {
			return false;
		}
	}
	if(!r.monitoring_target_id.empty()) {
		if(!entry.contains("monitoring_target_ids") || !entry["monitoring_target_ids"].is_array()) {
			return false;
		}
		const auto &target_ids = entry["monitoring_target_ids"];
		if(std::none_of(target_ids.begin(), target_ids.end(), [&r](const json &id) {
			return id.is_string() && id.get<std::string>() == r.monitoring_target_id;
		})) {
			return false;
		}
	}
	return true;
}

std::string alert_evaluator::make_state_key(const rule &r, const json &entry, bool is_interface) {
	std::ostringstream ss;
	ss << r.id;
	if(is_interface) {
		ss << "|interface=" << json_string_or_empty(entry, "interface_id")
		   << "|name=" << json_string_or_empty(entry, "name");
		return ss.str();
	}
	ss << "|proto=" << json_string_or_empty(entry, "proto")
	   << "|stream=" << json_string_or_empty(entry, "stream_key");
	const auto flow_key = json_string_or_empty(entry, "flow_key");
	if(!flow_key.empty()) {
		ss << "|flow=" << flow_key;
	}
	return ss.str();
}

json alert_evaluator::make_target_source(const rule &r, const json &entry, bool is_interface) {
	json source{
		{"alert_id", r.id},
		{"severity", r.severity},
		{"indicator_category", r.indicator_category},
		{"target", is_interface ? "interface" : (entry.contains("flow_key") ? "flow" : "stream")},
	};
	for(const auto &key : {"proto", "stream_key", "flow_key", "interface_id", "name"}) {
		if(entry.contains(key)) {
			source[key] = entry[key];
		}
	}
	if(!r.monitoring_target_id.empty()) source["monitoring_target_id"] = r.monitoring_target_id;
	return source;
}

alert_evaluator::rule_type alert_evaluator::parse_rule_type(const std::string &value) {
	if(value == "threshold") return rule_type::threshold;
	if(value == "counter_delta") return rule_type::counter_delta;
	m_interfaces->append_metrics(now, interface_metrics);

	json root{
		{"time", now},
		{"metrics", std::move(metrics_list)},
		{"interfaces", std::move(interface_metrics)},
	};
	if(packet.vlan.empty() == false) {
		root["vlan"] = tsv::to_json(packet.vlan);
	}

	return root;
}

void monitor::evaluate_alerts(double now, const json &metrics_root) {
	if(!m_alerts || m_alerts->empty()) return;
	m_alerts->evaluate(now,
	                   metrics_root.at("metrics").get<json::array_t>(),
	                   metrics_root.at("interfaces").get<json::array_t>());
}

void monitor::write_second_boundary_outputs(double now, const packet_context &packet) {
	update_second_boundary_state(now);
	auto metrics_root = build_metrics_root(now, packet);
	evaluate_alerts(now, metrics_root);
	m_logs->append_metrics_snapshot(metrics_root);
}
