			const auto &scope = entry["scope"];
			if(!scope.contains("kind") || !scope["kind"].is_string()) throw std::runtime_error("binding scope requires kind");

			binding b;
			bool scope_has_target = false;
			const auto kind = scope["kind"].get<std::string>();
			if(kind == "protocol") {
				if(scope.contains("proto")) {
					if(!scope["proto"].is_string()) throw std::runtime_error("protocol scope proto must be string");
					b.scope_proto = scope["proto"].get<std::string>();
				}
				if(scope.contains("target")) {
					if(!scope["target"].is_string()) throw std::runtime_error("protocol scope target must be string");
					b.scope_target = scope["target"].get<std::string>();
