					scope_has_target = true;
				}
				b.id = "protocol:" + b.scope_proto + ":" + b.scope_target;
			}
			else if(kind == "managed_target") {
				if(!scope.contains("target_id") || !scope["target_id"].is_string() || scope["target_id"].get<std::string>().empty()) throw std::runtime_error("managed_target scope requires target_id");
				b.monitoring_target_id = scope["target_id"].get<std::string>();
				if(scope.contains("target_type") && (!scope["target_type"].is_string() || (scope["target_type"] != "single" && scope["target_type"] != "group"))) throw std::runtime_error("managed_target target_type must be single or group");
				b.scope_priority = scope.contains("target_type") && scope["target_type"] == "group" ? 1 : 2;
				b.id = "managed_target:" + b.monitoring_target_id;
			}
			else throw std::runtime_error("binding scope kind must be protocol or managed_target");
			if(!binding_scopes.insert(b.id).second) throw std::runtime_error("duplicate binding scope " + b.id);

			const auto mode = entry["mode"].get<std::string>();
			const json *policy = nullptr;
			if(mode == "shared" || mode == "shared_with_adjustments") {
				if(!entry.contains("policy_id") || !entry["policy_id"].is_string() || !policies.contains(entry["policy_id"].get<std::string>())) throw std::runtime_error("shared binding requires a known policy_id");
				policy = &policies.at(entry["policy_id"].get<std::string>());
			}
			else if(mode == "individual") {
				if(!entry.contains("conditions") || !entry["conditions"].is_array() || entry["conditions"].empty()) throw std::runtime_error("individual binding requires non-empty conditions");
			}
			else if(mode == "disabled") {
				b.disabled = true;
			}
			else throw std::runtime_error("binding mode must be shared, individual, shared_with_adjustments, or disabled");

			auto attach_rule = [&](rule r) {
				if(!b.scope_proto.empty()) {
