				for(const auto &condition : (*policy)["conditions"]) {
					const auto condition_id = condition.at("id").get<std::string>();
					condition_ids.insert(condition_id);
					rule r = parse_rule(condition, (*policy)["id"].get<std::string>() + "." + condition_id);
					if(adjustments.contains(condition_id)) apply_adjustment(r, adjustments[condition_id]);
					attach_rule(std::move(r));
				}
				for(const auto &[condition_id, adjustment] : adjustments.items()) {
					if(!condition_ids.contains(condition_id)) throw std::runtime_error("individual adjustment refers to an unknown condition " + condition_id);
					(void)adjustment;
				}
				if(entry.contains("additional_conditions")) {
					if(mode != "shared_with_adjustments" || !entry["additional_conditions"].is_array()) throw std::runtime_error("additional_conditions requires shared_with_adjustments mode");
					std::set<std::string> additional_ids;
					for(const auto &condition : entry["additional_conditions"]) {
						const auto condition_id = condition.at("id").get<std::string>();
						if(!additional_ids.insert(condition_id).second) throw std::runtime_error("duplicate additional condition id " + condition_id);
						attach_rule(parse_rule(condition, b.id + ".additional." + condition_id));
					}
				}
			}
			else if(mode == "individual") {
				std::set<std::string> condition_ids;
				for(const auto &condition : entry["conditions"]) {
					const auto condition_id = condition.at("id").get<std::string>();
					if(!condition_ids.insert(condition_id).second) throw std::runtime_error("duplicate individual condition id " + condition_id);
					attach_rule(parse_rule(condition, b.id + "." + condition_id));
				}
			}
			if(mode == "disabled" && (entry.contains("policy_id") || entry.contains("conditions") || entry.contains("adjustments") || entry.contains("additional_conditions"))) throw std::runtime_error("disabled binding cannot contain conditions or a policy");
			m_bindings.push_back(std::move(b));
		}
		catch(const std::exception &e) {
			std::cerr << "alert_evaluator: invalid binding: " << e.what() << std::endl;
			m_bindings.clear();
			return -1;
		}
	}

	return 0;
