int alert_evaluator::load(const std::filesystem::path &path) {
	m_bindings.clear();
	m_states.clear();

	if(path.empty()) {
		return 0;
	}

	std::ifstream in(path);
	if(!in) {
		std::cerr << "alert_evaluator: failed to open " << path << std::endl;
		return -1;
	}

	json root;
	try {
		in >> root;
	}
	catch(const std::exception &e) {
		std::cerr << "alert_evaluator: failed to parse " << path << ": " << e.what() << std::endl;
		return -1;
	}

	if(!root.is_object() || !root.contains("policies") || !root["policies"].is_array() || !root.contains("bindings") || !root["bindings"].is_array()) {
		std::cerr << "alert_evaluator: monitoring policy format requires policies and bindings arrays" << std::endl;
		return -1;
	}

	auto parse_rule = [this](const json &entry, const std::string &compiled_id) {
		if(!entry.is_object()) throw std::runtime_error("condition must be an object");
		if(!entry.contains("id") || !entry["id"].is_string() || entry["id"].get<std::string>().empty()) throw std::runtime_error("condition requires a non-empty string id");
		if(!entry.contains("metric") || !entry["metric"].is_string() || entry["metric"].get<std::string>().empty()) throw std::runtime_error("condition requires a non-empty string metric");

		rule r;
		r.id = compiled_id;
		r.metric = entry["metric"].get<std::string>();
		if(entry.contains("target")) {
			if(!entry["target"].is_string()) throw std::runtime_error("condition target must be a string");
			r.target = entry["target"].get<std::string>();
			if(r.target != "any" && r.target != "flow" && r.target != "stream" && r.target != "interface") throw std::runtime_error("condition target is invalid");
		}
		if(entry.contains("proto")) {
			if(!entry["proto"].is_string()) throw std::runtime_error("condition proto must be a string");
			r.proto = entry["proto"].get<std::string>();
		}
		if(entry.contains("flow_roles")) {
			if(!entry["flow_roles"].is_array() || r.target != "flow") throw std::runtime_error("flow_roles requires flow target");
			for(const auto &role : entry["flow_roles"]) {
				if(!role.is_string() || role.get<std::string>().empty()) throw std::runtime_error("flow_roles must contain non-empty strings");
				if(std::find(r.flow_roles.begin(), r.flow_roles.end(), role.get<std::string>()) != r.flow_roles.end()) throw std::runtime_error("flow_roles must not contain duplicates");
				r.flow_roles.push_back(role.get<std::string>());
			}
		}
		if(entry.contains("indicator_category")) {
			if(!entry["indicator_category"].is_string() || (entry["indicator_category"] != "quality" && entry["indicator_category"] != "other")) throw std::runtime_error("indicator_category must be quality or other");
			r.indicator_category = entry["indicator_category"].get<std::string>();
		}
		if(entry.contains("type")) {
			if(!entry["type"].is_string()) throw std::runtime_error("condition type must be a string");
			r.type = parse_rule_type(entry["type"].get<std::string>());
		}
		if(entry.contains("operator")) {
			if(!entry["operator"].is_string()) throw std::runtime_error("condition operator must be a string");
			r.op = parse_compare_op(entry["operator"].get<std::string>());
		}
		auto read_number = [&entry](const char *key, double &value) {
			if(!entry.contains(key)) return;
			if(!entry[key].is_number()) throw std::runtime_error(std::string(key) + " must be numeric");
			value = entry[key].get<double>();
			if(!std::isfinite(value)) throw std::runtime_error(std::string(key) + " must be finite");
		};
		read_number("error_threshold", r.error_threshold);
		if(entry.contains("recover_threshold")) read_number("recover_threshold", r.recover_threshold);
		else r.recover_threshold = r.error_threshold;
		read_number("delta_threshold", r.delta_threshold);
		read_number("trigger_after_sec", r.trigger_after_sec);
		if(entry.contains("recover_after_sec")) read_number("recover_after_sec", r.recover_after_sec);
		else r.recover_after_sec = r.type == rule_type::counter_delta ? 3.0 : 0.0;
		read_number("missing_after_sec", r.missing_after_sec);
		read_number("inactive_after_sec", r.inactive_after_sec);
		if(r.trigger_after_sec < 0.0 || r.recover_after_sec < 0.0 || r.missing_after_sec < 0.0 || r.inactive_after_sec < 0.0) throw std::runtime_error("alert durations must be non-negative");
		if(r.type == rule_type::availability && r.inactive_after_sec <= 0.0) throw std::runtime_error("availability conditions require inactive_after_sec greater than zero");
		if(entry.contains("severity")) {
			if(!entry["severity"].is_string() || entry["severity"].get<std::string>().empty()) throw std::runtime_error("severity must be a non-empty string");
			r.severity = entry["severity"].get<std::string>();
		}
		if(entry.contains("enabled") && !entry["enabled"].is_boolean()) throw std::runtime_error("enabled must be boolean");
		r.enabled = read_bool(entry, "enabled", true);
		return r;
	};

	auto apply_adjustment = [](rule &r, const json &adjustment) {
		if(!adjustment.is_object()) throw std::runtime_error("individual adjustment must be an object");
		for(const auto &[key, value] : adjustment.items()) {
			if(key == "enabled") {
				if(!value.is_boolean()) throw std::runtime_error("individual adjustment enabled must be boolean");
				r.enabled = value.get<bool>();
			}
			else if(key == "severity") {
				if(!value.is_string() || value.get<std::string>().empty()) throw std::runtime_error("individual adjustment severity must be a non-empty string");
				r.severity = value.get<std::string>();
			}
			else if(key == "error_threshold" || key == "recover_threshold" || key == "delta_threshold" || key == "trigger_after_sec" || key == "recover_after_sec" || key == "missing_after_sec" || key == "inactive_after_sec") {
				if(!value.is_number() || !std::isfinite(value.get<double>())) throw std::runtime_error("individual adjustment numeric value must be finite");
				const auto number = value.get<double>();
				if((key == "trigger_after_sec" || key == "recover_after_sec" || key == "missing_after_sec" || key == "inactive_after_sec") && number < 0.0) throw std::runtime_error("individual adjustment duration must be non-negative");
				if(key == "error_threshold") r.error_threshold = number;
				else if(key == "recover_threshold") r.recover_threshold = number;
				else if(key == "delta_threshold") r.delta_threshold = number;
				else if(key == "trigger_after_sec") r.trigger_after_sec = number;
				else if(key == "recover_after_sec") r.recover_after_sec = number;
				else if(key == "missing_after_sec") r.missing_after_sec = number;
				else r.inactive_after_sec = number;
			}
			else throw std::runtime_error("unsupported individual adjustment field " + key);
		}
		if(r.type == rule_type::availability && r.inactive_after_sec <= 0.0) throw std::runtime_error("availability conditions require inactive_after_sec greater than zero");
	};

	std::map<std::string, json> policies;
	for(const auto &policy : root["policies"]) {
		if(!policy.is_object() || !policy.contains("id") || !policy["id"].is_string() || policy["id"].get<std::string>().empty() || !policy.contains("conditions") || !policy["conditions"].is_array()) {
			std::cerr << "alert_evaluator: policy requires id and conditions" << std::endl;
			return -1;
		}
		const auto id = policy["id"].get<std::string>();
		if(!policies.emplace(id, policy).second) {
			std::cerr << "alert_evaluator: duplicate policy id " << id << std::endl;
			return -1;
		}
		std::set<std::string> condition_ids;
		try {
			for(const auto &condition : policy["conditions"]) {
				const auto condition_id = condition.at("id").get<std::string>();
				if(!condition_ids.insert(condition_id).second) throw std::runtime_error("duplicate condition id " + condition_id);
				(void)parse_rule(condition, id + "." + condition_id);
			}
		}
		catch(const std::exception &e) {
			std::cerr << "alert_evaluator: invalid policy " << id << ": " << e.what() << std::endl;
			return -1;
		}
	}

	std::set<std::string> binding_scopes;
	for(const auto &entry : root["bindings"]) {
