#ifndef ALERT_EVALUATOR_H
#define ALERT_EVALUATOR_H

#include <filesystem>
#include <algorithm>
#include <map>
#include <optional>
#include <string>
#include <vector>

#include "event.h"
#include "json.h"

class alert_evaluator {
public:
	enum class rule_type {
		threshold,
		counter_delta,
		availability,
	};

	enum class compare_op {
		gt,
		ge,
		lt,
		le,
		eq,
		ne,
	};

	struct rule {
		std::string id;
		std::string target{"any"};
		std::string proto;
		std::vector<std::string> flow_roles;
		std::string indicator_category{"other"};
		std::string metric;
		rule_type type{rule_type::threshold};
		compare_op op{compare_op::gt};
		double error_threshold{0.0};
		double recover_threshold{0.0};
		double delta_threshold{0.0};
		double trigger_after_sec{0.0};
		double recover_after_sec{0.0};
		double missing_after_sec{0.0};
		double inactive_after_sec{0.0};
		std::string severity{"warning"};
		bool enabled{true};
		std::string monitoring_target_id;
		int scope_priority{0};
	};

	explicit alert_evaluator(event_sink &events);

	int load(const std::filesystem::path &path);
	bool empty() const noexcept { return m_bindings.empty(); }
	void evaluate(double now, const json::array_t &metrics, const json::array_t &interfaces);
	json::array_t active_alerts() const;

private:
	struct state {
		bool active{false};
		bool metric_available{false};
		bool metric_missing{false};
		bool has_last_value{false};
		double last_value{0.0};
		double last_error_time{0.0};
		double last_seen_time{0.0};
		double error_pending_since{0.0};
		double recovery_pending_since{0.0};
		json source{json::object()};
		json detail{json::object()};
	};

	// A binding is the unit of policy selection. Its rules are evaluated as a
	// set, rather than resolving unrelated rules from lower-priority scopes.
	struct binding {
		std::string id;
		std::string scope_target{"any"};
		std::string scope_proto;
		std::string monitoring_target_id;
		int scope_priority{0};
		bool disabled{false};
		std::vector<rule> rules;
	};

	event_sink &m_events;
	std::vector<binding> m_bindings;
	std::map<std::string, state> m_states;

	void evaluate_entry(double now, const rule &r, const json &entry, bool is_interface);
	void evaluate_threshold(double now, const rule &r, const json &entry, bool is_interface, const std::string &state_key, state &s, double value);
	void evaluate_counter_delta(double now, const rule &r, const json &entry, bool is_interface, const std::string &state_key, state &s, double value);
	void evaluate_availability(double now, const rule &r, const json &entry, bool is_interface, const std::string &state_key, state &s);
	void update_metric_availability(double now, const rule &r, const json &entry, bool is_interface, const std::string &state_key, state &s, bool available);
	void emit_alert(double now, const rule &r, const json &entry, bool is_interface, std::string action, double value, json detail);
	void emit_data_availability(double now, const rule &r, const json &entry, bool is_interface, const std::string &state_key, bool available);
	void emit_availability_alert(double now, const rule &r, const json &entry, bool is_interface, const std::string &state_key, bool available, double last_seen);
	void update_active_state(double now, const rule &r, const json &entry, bool is_interface, state &s, double value, json detail);

	static std::optional<double> metric_value(const json &entry, const std::string &path);
	static bool compare(double lhs, compare_op op, double rhs);
	static std::string compare_operator(compare_op op);
	static bool matches_target(const rule &r, const json &entry, bool is_interface);
	static bool matches_binding(const binding &b, const json &entry, bool is_interface);
	static std::string make_state_key(const rule &r, const json &entry, bool is_interface);
	static json make_target_source(const rule &r, const json &entry, bool is_interface);
	static rule_type parse_rule_type(const std::string &value);
	static compare_op parse_compare_op(const std::string &value);
};

#endif /* ALERT_EVALUATOR_H */
