void alert_evaluator::emit_alert(double now, const rule &r, const json &entry, bool is_interface, std::string action, double value, json detail) {
	detail["alert_id"] = r.id;
	detail["state_key"] = make_state_key(r, entry, is_interface);
	detail["severity"] = r.severity;
	detail["indicator_category"] = r.indicator_category;
	detail["action"] = action;
	detail["value"] = value;
	detail["comparison_operator"] = compare_operator(r.op);
	detail["error_threshold"] = r.error_threshold;
	detail["recover_threshold"] = r.recover_threshold;
	detail["trigger_after_sec"] = r.trigger_after_sec;
	detail["recover_after_sec"] = r.recover_after_sec;
	detail["missing_after_sec"] = r.missing_after_sec;
	detail["inactive_after_sec"] = r.inactive_after_sec;
	m_events.emit(event_record{.time_epoch = now, .type = action == "detected" ? "alert_detected" : "alert_recovered", .source = make_target_source(r, entry, is_interface), .detail = std::move(detail)});
}

void alert_evaluator::emit_data_availability(double now, const rule &r, const json &entry, bool is_interface, const std::string &state_key, bool available) {
	json detail{{"alert_id", r.id}, {"state_key", state_key + "|data"}, {"severity", r.severity}, {"indicator_category", r.indicator_category}, {"metric", r.metric}, {"missing_after_sec", r.missing_after_sec}, {"action", available ? "available" : "unavailable"}};
	m_events.emit(event_record{.time_epoch = now, .type = available ? "alert_data_available" : "alert_data_unavailable", .source = make_target_source(r, entry, is_interface), .detail = std::move(detail)});
}

void alert_evaluator::emit_availability_alert(double now, const rule &r, const json &entry, bool is_interface, const std::string &state_key, bool available, double last_seen) {
	json detail{{"alert_id", r.id}, {"state_key", state_key}, {"severity", r.severity}, {"indicator_category", r.indicator_category}, {"metric", r.metric}, {"type", "availability"}, {"inactive_after_sec", r.inactive_after_sec}, {"last_seen", last_seen}, {"outage_seconds", std::max(0.0, now - last_seen)}, {"action", available ? "available" : "unavailable"}};
	m_events.emit(event_record{.time_epoch = now, .type = available ? "alert_data_available" : "alert_data_unavailable", .source = make_target_source(r, entry, is_interface), .detail = std::move(detail)});
}

