	return ends_with(e.type, "_occurred") || ends_with(e.type, "_recovered");
}

std::string marker_action(const std::string &type) {
	if(type == "alert_data_unavailable") return "unavailable";
	if(type == "alert_data_available") return "available";
	if(ends_with(type, "_detected") || ends_with(type, "_occurred")) return "detected";
	if(ends_with(type, "_recovered")) return "recovered";
	return "event";
}

json make_marker_subject(const event_record &e) {
	json subject = e.source.is_object() ? e.source : json::object();
	if(!subject.contains("type")) {
		if(subject.contains("target") && subject["target"].is_string()) {
			subject["type"] = subject["target"];
		}
		else if(subject.contains("flow_key")) {
			subject["type"] = "flow";
		}
		else if(subject.contains("stream_key")) {
			subject["type"] = "stream";
		}
		else if(subject.contains("interface_id") || subject.contains("name")) {
			subject["type"] = "interface";
		}
	}
	return subject;
}

json make_marker_detail(const event_record &e) {
	json detail = e.detail.is_object() ? e.detail : json::object();
	detail["event_type"] = e.type;
	detail["action"] = marker_action(e.type);
	if(e.source.is_object()) {
		for(const auto &key : {"alert_id", "severity", "target", "proto", "stream_key", "flow_key", "interface_id", "name"}) {
			if(e.source.contains(key) && !detail.contains(key)) detail[key] = e.source[key];
		}
	}
	if(!detail.contains("label")) {
		if(detail.contains("alert_id") && detail["alert_id"].is_string()) detail["label"] = detail["alert_id"];
		else if(detail.contains("metric") && detail["metric"].is_string()) detail["label"] = detail["metric"];
		else detail["label"] = e.type;
	}
	if(!detail.contains("severity")) {
		detail["severity"] = (e.type == "alert_detected" || e.type == "alert_data_unavailable") ? "warning" : "info";
	}
	return detail;
}

