int emit_reclassified_timeline_rows(timeline_sink &timeline, const event_record &e) {
	if(!e.detail.is_object()) return 0;
	const auto from = e.detail.value("from", json::object());
	if(!from.is_object()) return 0;
	int rc = 0;
	auto emit_entries = [&](const char *field, const char *kind, const char *subject_type) {
		const auto entries = from.value(field, json::array());
		if(!entries.is_array()) return;
		for(const auto &entry : entries) {
			if(!entry.is_object()) continue;
			json subject = entry.value("source", json::object());
			if(!subject.is_object()) continue;
			subject["type"] = subject_type;
			json detail = entry.value("detail", json::object());
			if(!detail.is_object()) detail = json::object();
			detail["event_type"] = e.type;
			detail["to_proto"] = e.detail.value("to", json::object()).value("proto", std::string{});
			const int current = timeline.emit(e.time_epoch, kind, std::move(subject), std::move(detail));
			if(rc == 0 && current != 0) rc = current;
		}
	};
	emit_entries("flows", "flow_reclassified", "flow");
	emit_entries("streams", "stream_reclassified", "stream");
	return rc;
}

bool ends_with(const std::string &value, const std::string &suffix) {
	return value.size() >= suffix.size() &&
