/* -*- coding: utf-8 -*- */

#ifndef EVENT_H
#define EVENT_H

#include <cstdint>
#include <string>
#include <unordered_map>
#include <vector>

#include "json.h"

class writer;
class timeline_sink;
class time_rotating_writer;

struct event_record {
	double time_epoch{0.0};
	std::string type;
	json source{json::object()};
	json detail{json::object()};
};

class event_consumer {
public:
	virtual ~event_consumer() = default;
	virtual int handle_event(const event_record &e) = 0;
};

class event_sink {
public:
	event_sink() = default;
	virtual ~event_sink() = default;

	void add_consumer(event_consumer &consumer);
	void set_stream_display_name(std::string stream_key, std::string display_name);
	int emit(const event_record &e);

private:
	std::vector<event_consumer*> m_consumers;
	std::unordered_map<std::string, std::string> m_stream_display_names;
};

class event_log_sink
	: public event_consumer {
public:
	explicit event_log_sink(writer &w);
	virtual ~event_log_sink() = default;

	int handle_event(const event_record &e) override;

private:
	writer &m_writer;
};

class event_journal_sink
	: public event_consumer {
public:
	event_journal_sink(time_rotating_writer &writer, std::string capture_id);
	virtual ~event_journal_sink() = default;

	int handle_event(const event_record &e) override;

private:
	time_rotating_writer &m_writer;
	std::string m_capture_id;
	std::uint64_t m_seq{0};
};

class timeline_projector
	: public event_consumer {
public:
	explicit timeline_projector(timeline_sink &timeline);
	virtual ~timeline_projector() = default;

	int handle_event(const event_record &e) override;

private:
	timeline_sink &m_timeline;
};

class event_state {
public:
	explicit event_state(double recovery_retention_sec = 0.0,
	                     bool enable = true,
	                     bool mask = false);
	virtual ~event_state() = default;

	void clear();
	bool occur(double now);
	bool recover(double now);
	bool update(double now);
	bool remove(double now);

	void set_enable(bool enable) { m_enable = enable; }
	void set_mask(bool mask) { m_mask = mask; }
	bool active() const { return m_active; }
	bool pending_recovery() const { return m_recovery_pending; }
	bool stat() const { return m_enable && !m_mask && m_active; }

	std::uint64_t occurred_total() const { return m_occurred_total; }
	std::uint64_t fired_total() const { return m_fired_total; }
