import { useEffect, Fragment, useLayoutEffect, useMemo, useRef, useState, type CSSProperties, type KeyboardEvent as ReactKeyboardEvent, type MouseEvent as ReactMouseEvent, type PointerEvent as ReactPointerEvent } from "react";
import type { EventLogItem } from "../types/api";
import { getEvents } from "../api/client";
import { SearchInput } from "./ui/SearchInput";
import { Icon } from "./ui/Icon";
import { matchesSearch } from "./search";

const MAX_RENDERED_EVENTS = 8000;
const AUTO_FIT_SAMPLE_SIZE = 240;
const EVENT_LIST_STORAGE_KEY = "stm-events-column-widths";
const EVENT_ROW_SIDE_PADDING_PX = 8;
const EVENT_COLUMN_GAP_PX = 4;
const EVENT_MARKER_COLUMN_PX = 28;
const RELATED_EVENT_LOOKUP_WINDOW_SEC = 24 * 60 * 60;
const MIN_MESSAGE_COLUMN_PX = 120;
export const DEFAULT_EVENT_COLUMN_WIDTHS = { time: 180, level: 42, target: 260 };
const EVENT_COLUMN_LIMITS = {
  time: { min: 125, max: 260 },
  level: { min: 38, max: 76 },
  target: { min: 180, max: 600 }
} as const;

type EventColumn = keyof EventColumnWidths;
export type EventSortOrder = "desc" | "asc";

export type EventColumnWidths = {
  time: number;
  level: number;
  target: number;
};

type LocalSelectionScrollAnchor = {
  eventId: string;
  scrollTop: number;
  rowOffset: number;
};

type MeasurementAnchor = {
  event: EventLogItem;
  number: number;
};

type LocalSelectionSnapshot = {
  events: EventLogItem[];
  tab: EventLogTab;
  query: string;
  eventsRange: string;
  sortOrder: EventSortOrder;
  selectedEventId: string;
  selectedTimeSec: number | null;
  outsideRangeEvent: EventLogItem | null;
};

type EventRelation = {
  counterpartTypes: string[];
  direction: "before" | "after";
};

type RelatedEvent = {
  sourceId: string;
  event: EventLogItem;
};

type EventLogProps = {
  events: EventLogItem[];
  eventsRange: string;
  onChangeEventsRange: (value: string) => void;
  selectedStreamKey: string | null;
  selectedFlowKey: string | null;
  selectedInterfaceId: number | null;
  initialQuery?: string;
  query?: string;
  onChangeQuery?: (value: string) => void;
  showSearch?: boolean;
  tab?: EventLogTab;
  onChangeTab?: (tab: EventLogTab) => void;
  showHeader?: boolean;
  selectedTimeSec?: number | null;
  onSelectTime?: (timeSec: number) => void;
  selectedEvent?: EventLogItem | null;
  onSelectEvent?: (event: EventLogItem | null) => void;
  onInspectTarget?: (event: EventLogItem) => void;
  syncTimeOnRowClick?: boolean;
  onSyncTime?: (timeSec: number) => void;
  columnWidths?: EventColumnWidths;
  onChangeColumnWidths?: (widths: EventColumnWidths) => void;
  sortOrder?: EventSortOrder;
  onChangeSortOrder?: (order: EventSortOrder) => void;
  detailPresentation?: "panel" | "inline";
};

export type EventLogTab = "all" | "selected";

export function EventLog({
  events,
  eventsRange,
  onChangeEventsRange,
  selectedStreamKey,
  selectedFlowKey,
  selectedInterfaceId,
  initialQuery = "",
  query: controlledQuery,
  onChangeQuery,
  showSearch = true,
  tab: controlledTab,
  onChangeTab,
  showHeader = true,
  selectedTimeSec = null,
  onSelectTime,
  selectedEvent: externallySelectedEvent,
  onSelectEvent,
  onInspectTarget,
  syncTimeOnRowClick = true,
  sortOrder: controlledSortOrder,
  onChangeSortOrder,
  detailPresentation = "panel",
  onSyncTime,
  columnWidths: controlledColumnWidths,
  onChangeColumnWidths
}: EventLogProps) {
  const [internalTab, setInternalTab] = useState<EventLogTab>("all");
  const [internalSortOrder, setInternalSortOrder] = useState<EventSortOrder>("desc");
  const [internalQuery, setInternalQuery] = useState(initialQuery);
  const [internalColumnWidths, setInternalColumnWidths] = useState<EventColumnWidths>(loadStoredColumnWidths);
  const [selectedEvent, setSelectedEvent] = useState<EventLogItem | null>(null);
  const [measurementAnchors, setMeasurementAnchors] = useState<MeasurementAnchor[]>([]);

  useEffect(() => {
    if (externallySelectedEvent === undefined) return;
    setSelectedEvent(externallySelectedEvent);
  }, [externallySelectedEvent?.id]);
  const [relatedEvent, setRelatedEvent] = useState<RelatedEvent | null>(null);
  const [localSelectionSnapshot, setLocalSelectionSnapshot] = useState<LocalSelectionSnapshot | null>(null);
  const [listWidth, setListWidth] = useState(0);
  const [showLatestJump, setShowLatestJump] = useState(false);
  const listRef = useRef<HTMLDivElement | null>(null);
  const listFrameRef = useRef<HTMLDivElement | null>(null);
  const scrollSnapshotRef = useRef({ top: 0, height: 0 });
  const followLatestRef = useRef(true);
  const eventRowRefs = useRef(new Map<string, HTMLButtonElement>());
  const lastAutoScrolledKeyRef = useRef<string | null>(null);
  const locallySelectedEventIdRef = useRef<string | null>(null);
  const localSelectionScrollAnchorRef = useRef<LocalSelectionScrollAnchor | null>(null);
  const keyboardSelectionEventIdRef = useRef<string | null>(null);
  const relatedEventNavigationIdRef = useRef<string | null>(null);
  const tab = controlledTab ?? internalTab;
  const setTab = onChangeTab ?? setInternalTab;
  const sortOrder = controlledSortOrder ?? internalSortOrder;
  const setSortOrder = onChangeSortOrder ?? setInternalSortOrder;
  const query = controlledQuery ?? internalQuery;
  const setQuery = onChangeQuery ?? setInternalQuery;
  const columnWidths = normalizeColumnWidths(controlledColumnWidths ?? internalColumnWidths);
  const scopedEvents = tab === "all" ? events : events.filter((event) => {
    if (selectedFlowKey) return event.flowKey === selectedFlowKey || event.streamKey === selectedStreamKey;
    if (selectedStreamKey) return event.streamKey === selectedStreamKey;
    if (selectedInterfaceId !== null) return event.interfaceId === selectedInterfaceId;
    return false;
  });
  const normalizedQuery = query.trim();
  const matchingEvents = [...(normalizedQuery ? scopedEvents.filter((event) => eventMatches(event, query)) : scopedEvents)].sort((left, right) => sortOrder === "desc" ? right.time - left.time : left.time - right.time);
  const visibleEvents = localSelectionSnapshot?.events ?? matchingEvents;
  const sortedMeasurementAnchors = useMemo(() => [...measurementAnchors].sort((left, right) => left.event.time - right.event.time), [measurementAnchors]);
  const activeRelatedEvent = relatedEvent !== null && relatedEvent.sourceId === selectedEvent?.id ? relatedEvent.event : null;
  const relatedEventOutsideRange = activeRelatedEvent !== null && !visibleEvents.some((event) => event.id === activeRelatedEvent.id);
  const pinnedOutsideRangeEvent = localSelectionSnapshot?.outsideRangeEvent ?? (relatedEventOutsideRange ? activeRelatedEvent : null);
  const baseRenderedEvents = visibleEvents.slice(0, MAX_RENDERED_EVENTS);
  const pinnedOutsideRangeMissing = pinnedOutsideRangeEvent !== null && !baseRenderedEvents.some((event) => event.id === pinnedOutsideRangeEvent.id);
  const relatedEventAtTop = pinnedOutsideRangeMissing && (baseRenderedEvents.length === 0 || (sortOrder === "desc" ? pinnedOutsideRangeEvent.time > baseRenderedEvents[0].time : pinnedOutsideRangeEvent.time < baseRenderedEvents[0].time));
  const renderedEvents = pinnedOutsideRangeMissing
    ? relatedEventAtTop
      ? [pinnedOutsideRangeEvent, ...baseRenderedEvents.slice(0, MAX_RENDERED_EVENTS - 1)]
      : [...baseRenderedEvents.slice(0, MAX_RENDERED_EVENTS - 1), pinnedOutsideRangeEvent]
    : baseRenderedEvents;
  const timeSelectedEvent = useMemo(() => closestEventWithin(renderedEvents, selectedTimeSec), [renderedEvents, selectedTimeSec]);
  const primarySelectedEventId = selectedEvent && renderedEvents.some((event) => event.id === selectedEvent.id)
    ? selectedEvent.id
    : timeSelectedEvent?.id ?? null;
  const visibleSignature = `${visibleEvents[0]?.id ?? ""}:${visibleEvents.length}:${visibleEvents[visibleEvents.length - 1]?.id ?? ""}`;
  const effectiveColumnWidths = useMemo(() => fitColumnWidths(columnWidths, listWidth), [columnWidths, listWidth]);
  const columnStyle = useMemo(() => ({
    "--event-time-width": `${effectiveColumnWidths.time}px`,
    "--event-level-width": `${effectiveColumnWidths.level}px`,
    "--event-target-width": `${effectiveColumnWidths.target}px`
  }) as CSSProperties, [effectiveColumnWidths]);

  useEffect(() => {
    setMeasurementAnchors([]);
  }, [eventsRange]);

  useLayoutEffect(() => {
    const list = listRef.current;
    if (!list) return;
    const atLatest = sortOrder === "desc" ? list.scrollTop <= 8 : list.scrollTop + list.clientHeight >= list.scrollHeight - 8;
    followLatestRef.current = atLatest;
    setShowLatestJump(!atLatest);
  }, [sortOrder]);
  useLayoutEffect(() => {
    const element = listFrameRef.current;
    if (!element) return;
    const update = () => setListWidth(element.clientWidth);
    update();
    const observer = new ResizeObserver(update);
    observer.observe(element);
    return () => observer.disconnect();
  }, []);

  useLayoutEffect(() => {
    const snapshot = localSelectionSnapshot;
    if (!snapshot) return;
    const selectionIsCurrent = selectedEvent !== null
      && snapshot.selectedEventId === selectedEvent.id
      && (snapshot.selectedTimeSec === null || snapshot.selectedTimeSec === selectedTimeSec)
      && snapshot.tab === tab
      && snapshot.query === normalizedQuery
      && snapshot.sortOrder === sortOrder
      && snapshot.eventsRange === eventsRange;
    if (selectionIsCurrent) return;
    setLocalSelectionSnapshot(null);
  }, [eventsRange, localSelectionSnapshot, normalizedQuery, selectedEvent, selectedTimeSec, sortOrder, tab]);

  useEffect(() => {
    const source = selectedEvent;
    const relation = source ? eventRelationFor(source) : null;
    if (!source || !relation) {
      setRelatedEvent(null);
      return;
    }

    const localRelated = findRelatedEvent(events, source, relation);
    if (localRelated) {
      setRelatedEvent({ sourceId: source.id, event: localRelated });
      return;
    }

    const target = source.flowKey ? { flowKey: source.flowKey } : source.streamKey ? { streamKey: source.streamKey } : null;
    if (!target) return;
    const now = Date.now() / 1000;
    const from = relation.direction === "before" ? Math.max(0, source.time - RELATED_EVENT_LOOKUP_WINDOW_SEC) : source.time;
    const to = relation.direction === "after" ? Math.min(now, source.time + RELATED_EVENT_LOOKUP_WINDOW_SEC) : source.time;
    if (to <= from) return;

    let cancelled = false;
    void Promise.all(relation.counterpartTypes.map((type) => getEvents({ ...target, type, from, to, limit: 100 })))
      .then((results) => {
        if (cancelled) return;
        const related = findRelatedEvent(results.flat(), source, relation);
        if (related) setRelatedEvent({ sourceId: source.id, event: related });
      })
      .catch(() => { /* Keep the detail neutral when history lookup is unavailable. */ });
    return () => { cancelled = true; };
  }, [selectedEvent?.id]);

  useEffect(() => {
    const source = selectedEvent;
    const relation = source ? eventRelationFor(source) : null;
    if (!source || !relation) return;
    const localRelated = findRelatedEvent(events, source, relation);
    if (localRelated) setRelatedEvent({ sourceId: source.id, event: localRelated });
  }, [events, selectedEvent?.id]);

