type EventTargetParts = {
  nic: string;
  vlan: string;
  proto: string;
  src: string;
  dst: string;
  full: string;
};

function measurementTargetParts(event: EventLogItem): EventTargetParts {
  const full = event.targetLabel ?? event.proto ?? event.scope;
  const parts = full.split(/\s*·\s*/).map((part) => part.trim()).filter(Boolean);
  const protoIndex = event.proto
    ? parts.findIndex((part) => part.toLowerCase() === event.proto?.toLowerCase())
    : parts.findIndex((part) => /^(?:RTP|RTCP|SRT|HLS|HTTP|HTTPS|UDP|TCP)$/i.test(part));
  const vlanIndex = parts.findIndex((part) => /^(?:VLAN\s+.+|Untagged|VLAN unknown)$/i.test(part));
  const endpoint = protoIndex >= 0 ? parts.slice(protoIndex + 1).join(" · ") : "";
  const [src, dst] = splitMeasurementEndpoint(endpoint || (protoIndex < 0 ? full : ""));
  return {
    nic: vlanIndex > 0 ? parts[vlanIndex - 1] : protoIndex > 0 ? parts[protoIndex - 1] : event.interfaceId === undefined ? "—" : `if:${event.interfaceId}`,
    vlan: vlanIndex >= 0 ? parts[vlanIndex] : "—",
    proto: event.proto ?? (protoIndex >= 0 ? parts[protoIndex] : "—"),
    src,
    dst,
    full
  };
}

function splitMeasurementEndpoint(endpoint: string): [string, string] {
  const match = endpoint.match(/^(.*?)\s*(?:→|->|↔|<->)\s*(.*?)$/);
  if (match) return [match[1] || "—", match[2] || "—"];
  return [endpoint || "—", "—"];
}

function measurementRowTitle(from: MeasurementAnchor, to: MeasurementAnchor, fromTarget: EventTargetParts, toTarget: EventTargetParts) {
  return `#${from.number} ${formatEventTime(from.event.time)}\n${fromTarget.full}\n\n#${to.number} ${formatEventTime(to.event.time)}\n${toTarget.full}`;
