function formatDuration(seconds: number) {
  if (seconds < 1) return `${(seconds * 1000).toFixed(1)} ms`;
  if (seconds < 60) return `${seconds.toFixed(3)} s`;
  const minutes = Math.floor(seconds / 60);
  const remaining = seconds - minutes * 60;
  if (minutes < 60) return `${minutes}m ${remaining.toFixed(3)}s`;
  const hours = Math.floor(minutes / 60);
  return `${hours}h ${minutes % 60}m ${remaining.toFixed(3)}s`;
}

function eventRelationFor(event: EventLogItem): EventRelation | null {
  if (event.type === "alert_detected") return { counterpartTypes: ["alert_recovered"], direction: "after" };
  if (event.type === "alert_recovered") return { counterpartTypes: ["alert_detected"], direction: "before" };
  if (event.type === "alert_data_unavailable") return { counterpartTypes: ["alert_data_available"], direction: "after" };
  if (event.type === "alert_data_available") return { counterpartTypes: ["alert_data_unavailable"], direction: "before" };
  const lifecycle = event.type.match(/^(stream|flow)_(detected|recovered|lost)$/);
  if (lifecycle) {
    const [, subject, action] = lifecycle;
    if (action === "lost") return { counterpartTypes: [`${subject}_detected`, `${subject}_recovered`], direction: "before" };
    return { counterpartTypes: [`${subject}_lost`], direction: "after" };
  }
  if (event.type.endsWith("_occurred")) return { counterpartTypes: [`${event.type.slice(0, -"occurred".length)}recovered`], direction: "after" };
  if (event.type.endsWith("_recovered")) return { counterpartTypes: [`${event.type.slice(0, -"recovered".length)}occurred`], direction: "before" };
  return null;
}

function alertStateKey(event: EventLogItem) {
