type EventTargetParts = {
  nic: string;
  vlan: string;
  proto: string;
  src: string;
  dst: string;
  full: string;
};

function measurementTargetParts(event: EventLogItem): EventTargetParts {
  const full = event.targetLabel ?? event.proto ?? event.scope;
  const parts = full.split(/\s*·\s*/).map((part) => part.trim()).filter(Boolean);
  const protoIndex = event.proto
    ? parts.findIndex((part) => part.toLowerCase() === event.proto?.toLowerCase())
    : parts.findIndex((part) => /^(?:RTP|RTCP|SRT|HLS|HTTP|HTTPS|UDP|TCP)$/i.test(part));
  const vlanIndex = parts.findIndex((part) => /^(?:VLAN\s+.+|Untagged|VLAN unknown)$/i.test(part));
  const endpoint = protoIndex >= 0 ? parts.slice(protoIndex + 1).join(" · ") : "";
  const [src, dst] = splitMeasurementEndpoint(endpoint || (protoIndex < 0 ? full : ""));
  return {
    nic: vlanIndex > 0 ? parts[vlanIndex - 1] : protoIndex > 0 ? parts[protoIndex - 1] : event.interfaceId === undefined ? "—" : `if:${event.interfaceId}`,
    vlan: vlanIndex >= 0 ? parts[vlanIndex] : "—",
    proto: event.proto ?? (protoIndex >= 0 ? parts[protoIndex] : "—"),
    src,
    dst,
    full
  };
}

function splitMeasurementEndpoint(endpoint: string): [string, string] {
  const match = endpoint.match(/^(.*?)\s*(?:→|->|↔|<->)\s*(.*?)$/);
  if (match) return [match[1] || "—", match[2] || "—"];
  return [endpoint || "—", "—"];
}

function measurementRowTitle(from: MeasurementAnchor, to: MeasurementAnchor, fromTarget: EventTargetParts, toTarget: EventTargetParts) {
  return `#${from.number} ${formatEventTime(from.event.time)}\n${fromTarget.full}\n\n#${to.number} ${formatEventTime(to.event.time)}\n${toTarget.full}`;
}

function eventDetailRecord(value: unknown): Record<string, unknown> | null {
  return value !== null && typeof value === "object" && !Array.isArray(value) ? value as Record<string, unknown> : null;
}

function alertDetailRows(event: EventLogItem): Array<[string, string]> {
  if (!["alert_detected", "alert_recovered", "alert_data_unavailable", "alert_data_available"].includes(event.type)) return [];
  const detail = eventDetailRecord(event.detail);
  if (!detail) return [];
  const text = (key: string) => detail[key] === undefined || detail[key] === null ? undefined : String(detail[key]);
  const number = (key: string) => typeof detail[key] === "number" ? String(detail[key]) : text(key);
  const duration = (key: string) => {
    const value = detail[key];
    return typeof value === "number" ? `${value} s` : text(key);
  };
  const rows: Array<[string, string | undefined]> = [
    ["Alert rule", text("alert_id")],
    ["Metric", text("metric")],
    ["Current value", number("value")],
    ["Operator", text("comparison_operator") ?? text("operator")],
    ["Trigger threshold", number("error_threshold") ?? number("threshold")],
    ["Recovery threshold", number("recover_threshold")],
    ["Trigger after", duration("trigger_after_sec")],
    ["Recover after", duration("recover_after_sec")],
    ["Missing after", duration("missing_after_sec")],
    ["Severity", text("severity")]
  ];
  return rows.filter((row): row is [string, string] => row[1] !== undefined);
}

function EventContext({ event, onClose, onSyncTime, onInspect, relatedEvent, relatedOutsideRange = false, onSelectRelated, inline = false }: { event: EventLogItem; onClose: () => void; onSyncTime?: () => void; onInspect?: () => void; relatedEvent?: EventLogItem | null; relatedOutsideRange?: boolean; onSelectRelated?: () => void; inline?: boolean }) {
  const alertRows = alertDetailRows(event);
  return (
    <aside className={`event-context${inline ? " event-context-inline" : ""}`} aria-label="Selected event detail">
      <div className="event-context-header">
        <strong>Event detail</strong>
        <div className="event-context-actions">
          {onSyncTime && <button type="button" className="event-context-sync" onClick={onSyncTime} data-tooltip-key="tooltip.setDashboardTime">Sync time</button>}
          {onInspect && <button type="button" className="event-context-sync" onClick={onInspect}>Inspect</button>}
          <button type="button" onClick={onClose} aria-label="Close event detail" data-tooltip-key="tooltip.closeEventDetail"><Icon name="close" size={16} /></button>
        </div>
      </div>
      <dl>
        <dt>Time</dt><dd>{formatEventTime(event.time)}</dd>
        <dt>Level</dt><dd>{event.level}</dd>
        <dt>Type</dt><dd>{event.type}</dd>
        <dt>Target</dt><dd>{event.targetLabel ?? event.proto ?? event.scope}</dd>
      </dl>
      {alertRows.length > 0 && <dl className="event-context-alert" aria-label="Alert detail">{alertRows.map(([label, value]) => <Fragment key={label}><dt>{label}</dt><dd>{value}</dd></Fragment>)}</dl>}
      {relatedEvent && onSelectRelated && <div className="event-context-related">
        <span>Go to related event</span>
        <button type="button" onClick={onSelectRelated} data-tooltip-key="tooltip.relatedEvent" aria-label={`Go to related event: ${relatedEvent.message} · ${formatEventTime(relatedEvent.time)}`}><span className="event-context-related-message">{relatedEvent.message}</span><time className="event-context-related-time" dateTime={new Date(relatedEvent.time * 1000).toISOString()}>{formatEventTime(relatedEvent.time)}</time></button>
        {relatedOutsideRange && <small>Outside current range</small>}
      </div>}
      <p>{event.message}</p>
      {event.detail !== undefined && <details className="event-context-raw"><summary>Raw event data</summary><pre>{JSON.stringify(event.detail, null, 2)}</pre></details>}
    </aside>
  );
}

function formatDuration(seconds: number) {
  if (seconds < 1) return `${(seconds * 1000).toFixed(1)} ms`;
  if (seconds < 60) return `${seconds.toFixed(3)} s`;
  const minutes = Math.floor(seconds / 60);
  const remaining = seconds - minutes * 60;
  if (minutes < 60) return `${minutes}m ${remaining.toFixed(3)}s`;
  const hours = Math.floor(minutes / 60);
  return `${hours}h ${minutes % 60}m ${remaining.toFixed(3)}s`;
}

function eventRelationFor(event: EventLogItem): EventRelation | null {
  if (event.type === "alert_detected") return { counterpartTypes: ["alert_recovered"], direction: "after" };
  if (event.type === "alert_recovered") return { counterpartTypes: ["alert_detected"], direction: "before" };
  if (event.type === "alert_data_unavailable") return { counterpartTypes: ["alert_data_available"], direction: "after" };
  if (event.type === "alert_data_available") return { counterpartTypes: ["alert_data_unavailable"], direction: "before" };
  const lifecycle = event.type.match(/^(stream|flow)_(detected|recovered|lost)$/);
  if (lifecycle) {
    const [, subject, action] = lifecycle;
    if (action === "lost") return { counterpartTypes: [`${subject}_detected`, `${subject}_recovered`], direction: "before" };
    return { counterpartTypes: [`${subject}_lost`], direction: "after" };
  }
  if (event.type.endsWith("_occurred")) return { counterpartTypes: [`${event.type.slice(0, -"occurred".length)}recovered`], direction: "after" };
  if (event.type.endsWith("_recovered")) return { counterpartTypes: [`${event.type.slice(0, -"recovered".length)}occurred`], direction: "before" };
  return null;
}

function alertStateKey(event: EventLogItem) {
  const detail = eventDetailRecord(event.detail);
  return typeof detail?.state_key === "string" && detail.state_key ? detail.state_key : null;
}

import type { EventLogItem } from "./types";

type AnyRecord = Record<string, any>;

export function normalizeEventLine(line: string): EventLogItem | undefined {
  const raw = JSON.parse(line) as AnyRecord;
  const time = Number(raw.time ?? Date.now() / 1000);
  const type = String(raw.type ?? "event");
  const source = raw.source ?? {};
  const detail = raw.detail;
  const streamKey = source.stream_key ? String(source.stream_key) : undefined;
  const flowKey = source.flow_key ? String(source.flow_key) : undefined;
  const proto = source.proto ? String(source.proto) : undefined;
  const interfaceId = numericInterfaceId(source.interface_id) ?? interfaceIdFromKey(flowKey) ?? interfaceIdFromKey(streamKey);
  return {
    id: typeof raw.record_id === "string" && raw.record_id ? raw.record_id : `${time}:${type}:${streamKey ?? "system"}:${flowKey ?? ""}`,
    time,
    type,
    level: levelForType(type, detail),
    scope: flowKey ? "flow" : streamKey ? "stream" : "system",
    proto,
    interfaceId,
    streamKey,
    flowKey,
    targetLabel: targetLabel(source, streamKey, flowKey, detail),
    message: messageForType(type, detail),
    detail
  };
}

function levelForType(type: string, detail: unknown): EventLogItem["level"] {
  if (type === "capture_health_state_changed") {
    const state = stringValue(recordValue(detail)?.to);
    if (state === "critical") return "error";
    if (state === "warning" || state === "unknown") return "warn";
  }
  if (type.endsWith("_recovered") || type === "alert_data_available") return "info";
  if (type === "alert_detected" || type === "alert_data_unavailable") {
    const severity = stringValue(recordValue(detail)?.severity)?.toLowerCase();
    if (severity === "error" || severity === "critical") return "error";
    if (severity === "warning" || severity === "warn") return "warn";
  }
  if (/error|failed|failure/i.test(type)) return "error";
  if (/warn|stale|drop|loss|timeout/i.test(type)) return "warn";
  return "info";
}

function messageForType(type: string, detail?: AnyRecord) {
  if (type === "transport_reclassified") {
    const from = stringValue(recordValue(detail)?.from?.proto) ?? "transport";
    const to = stringValue(recordValue(detail)?.to?.proto) ?? "specialized protocol";
    return `${from} → ${to} reclassified`;
  }
  return type
    .split("_")
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join(" ");
}

function targetLabel(source: AnyRecord, streamKey?: string, flowKey?: string, detail?: AnyRecord) {
  if (!streamKey && !flowKey) {
    const connection = recordValue(detail)?.connection;
    const a = stringValue(connection?.endpoint_a);
    const b = stringValue(connection?.endpoint_b);
    if (a && b) return `${a} ↔ ${b}`;
  }
  if (!streamKey && !flowKey) return "System";

  const scope = recordValue(source.scope);
  const nic = stringValue(scope?.interface_name) ?? stringValue(source.interface_name) ?? interfaceLabel(source.interface_id);
  const vlan = vlanLabel(scope?.vlan ?? source.vlan, scope);
  const endpoint = endpointLabel(detail?.endpoint, flowKey, streamKey);
  return [stringValue(source.name), nic, vlan, stringValue(source.proto), endpoint].filter((part): part is string => Boolean(part)).join(" · ") || "Stream";
}

function endpointLabel(detailEndpoint: unknown, flowKey?: string, streamKey?: string) {
  const endpoint = recordValue(detailEndpoint);
  const src = stringValue(endpoint?.src) ?? keyField(flowKey, "src");
  const dst = stringValue(endpoint?.dst) ?? keyField(flowKey, "dst");
  if (src && dst) return `${src} → ${dst}`;

  const a = stringValue(endpoint?.a) ?? keyField(streamKey, "a");
  const b = stringValue(endpoint?.b) ?? keyField(streamKey, "b");
  if (a && b) return `${a} → ${b}`;

  return stringValue(endpoint?.service)
    ?? stringValue(endpoint?.session_dst)
    ?? keyField(streamKey, "session_dst")
    ?? keyField(streamKey, "ep")
    ?? dst
    ?? src;
}

function vlanLabel(vlan: unknown, scope?: AnyRecord) {
  const layers = Array.isArray(scope?.layers) ? scope.layers : [];
  const vlanLayer = layers.map(recordValue).find((layer) => layer?.kind === "vlan");
  const vlanId = stringValue(vlanLayer?.id) ?? valueText(recordValue(vlan)?.id) ?? valueText(vlan);
  if (vlanId) return `VLAN ${vlanId}`;
  if (vlan === null || scope !== undefined || layers.length > 0) return "Untagged";
  return "VLAN unknown";
}

function keyField(key: string | undefined, field: string) {
  if (!key) return undefined;
  const prefix = `${field}=`;
  const value = key.split("|").find((part) => part.startsWith(prefix))?.slice(prefix.length);
  return value || undefined;
}

function interfaceLabel(value: unknown) {
  const id = numericInterfaceId(value);
  return id === undefined ? "NIC unknown" : `if:${id}`;
}

function numericInterfaceId(value: unknown) {
  const number = typeof value === "number" ? value : typeof value === "string" ? Number(value) : Number.NaN;
  return Number.isInteger(number) ? number : undefined;
}

function recordValue(value: unknown): AnyRecord | undefined {
  return value && typeof value === "object" && !Array.isArray(value) ? value as AnyRecord : undefined;
}

function stringValue(value: unknown) {
  return typeof value === "string" && value.length > 0 ? value : undefined;
}

function valueText(value: unknown) {
  return typeof value === "string" || typeof value === "number" ? String(value) : undefined;
}
