    const context = document.createElement("canvas").getContext("2d");
    if (!context) return;
    context.font = getComputedStyle(row ?? list).font;
    const widest = renderedEvents.slice(0, AUTO_FIT_SAMPLE_SIZE).reduce((max, item) => Math.max(max, context.measureText(eventColumnText(item, column)).width), 0);
    const limits = EVENT_COLUMN_LIMITS[column];
    applyColumnWidths({ ...columnWidths, [column]: clamp(Math.ceil(widest) + 12, limits.min, limits.max) });
  };

  const captureLocalSelectionAnchor = (event: EventLogItem) => {
    const list = listRef.current;
    const row = eventRowRefs.current.get(event.id);
    if (!list || !row) return;
    localSelectionScrollAnchorRef.current = {
      eventId: event.id,
      scrollTop: list.scrollTop,
      rowOffset: row.getBoundingClientRect().top - list.getBoundingClientRect().top
    };
  };

  const toggleMeasurementAnchor = (event: EventLogItem) => {
    setMeasurementAnchors((current) => {
      if (current.some((anchor) => anchor.event.id === event.id)) {
        return current.filter((anchor) => anchor.event.id !== event.id).map((anchor, index) => ({ ...anchor, number: index + 1 }));
      }
      return [...current, { event, number: current.length + 1 }];
    });
  };

  const toggleSortOrder = () => setSortOrder(sortOrder === "desc" ? "asc" : "desc");

  const jumpToLatest = () => {
    const list = listRef.current;
    if (!list) return;
    list.scrollTop = sortOrder === "desc" ? 0 : list.scrollHeight;
    followLatestRef.current = true;
    scrollSnapshotRef.current = { top: list.scrollTop, height: list.scrollHeight };
    setShowLatestJump(false);
  };

  const createLocalSelectionSnapshot = (event: EventLogItem, snapshotEvents: EventLogItem[], snapshotTime: number | null, outsideRangeEvent: EventLogItem | null = null): LocalSelectionSnapshot => ({
    events: snapshotEvents,
    tab,
    query: normalizedQuery,
    eventsRange,
    sortOrder,
    selectedEventId: event.id,
    selectedTimeSec: snapshotTime,
    outsideRangeEvent
  });
  const selectEventFromPointer = (event: EventLogItem, snapshotEvents = visibleEvents, outsideRangeEvent: EventLogItem | null = null) => {
    keyboardSelectionEventIdRef.current = null;
    selectEvent(event, snapshotEvents, outsideRangeEvent);
  };

  const closeSelectedEvent = () => {
    locallySelectedEventIdRef.current = null;
    keyboardSelectionEventIdRef.current = null;
    lastAutoScrolledKeyRef.current = null;
    setLocalSelectionSnapshot(null);
    setSelectedEvent(null);
    onSelectEvent?.(null);
  };

  const syncEventTime = (event: EventLogItem, callback: ((timeSec: number) => void) | undefined, snapshotEvents = visibleEvents, outsideRangeEvent: EventLogItem | null = null) => {
    if (!callback) return;
    captureLocalSelectionAnchor(event);
    locallySelectedEventIdRef.current = event.id;
    setLocalSelectionSnapshot(createLocalSelectionSnapshot(event, snapshotEvents, event.time, outsideRangeEvent));
    callback(event.time);
  };

  const selectEvent = (event: EventLogItem, snapshotEvents = visibleEvents, outsideRangeEvent: EventLogItem | null = null) => {
    captureLocalSelectionAnchor(event);
    setSelectedEvent(event);
    if (syncTimeOnRowClick) syncEventTime(event, onSelectTime, snapshotEvents, outsideRangeEvent);
    onSelectEvent?.(event);
  };

