let activeLocale = "en";

export function setFormatLocale(locale: string) { activeLocale = locale; }

export type MetricValueKind = "bitrate" | "rate" | "bytes" | "count" | "duration" | "percent" | "plain";

export type MetricScalePreference = "auto" | "base" | "K" | "M" | "G" | "T";

export type MetricDisplayScale = {
  kind: MetricValueKind;
  divisor: number;
  unit: string;
  prefix: string;
  includeZero: boolean;
};

export function metricValueKind(metricKey = "", unit = ""): MetricValueKind {
  if (metricKey === "utilization" || metricKey.endsWith(".utilization") || unit === "%") return "percent";
  if (unit === "bps" || /bitrate|bandwidth|headroom/.test(metricKey)) return "bitrate";
  if (unit === "pps" || /packet_rate/.test(metricKey)) return "rate";
  if (unit === "B" || unit === "bytes" || /bytes/.test(metricKey)) return "bytes";
  if (unit === "s" || unit === "ms" || unit === "us" || unit === "µs" || unit === "ns") return "duration";
  if (/packets|dropped|errors|gap|dup|reorder|count|total/.test(metricKey)) return "count";
  return "plain";
}

export function metricDisplayScale(metricKey: string | undefined, unit: string | undefined, values: readonly number[] = [], preference: MetricScalePreference = "auto"): MetricDisplayScale {
  const kind = metricValueKind(metricKey, unit);
  const magnitude = values.reduce((max, value) => Number.isFinite(value) ? Math.max(max, Math.abs(value)) : max, 0);
  if (kind === "percent") return { kind, divisor: 0.01, unit: "%", prefix: "", includeZero: true };
  if (kind === "duration") return durationScale(unit, magnitude);
  if (kind === "bitrate" || kind === "rate" || kind === "bytes" || kind === "count") {
    const automaticExponent = Math.max(0, Math.min(4, Math.floor(Math.log10(Math.max(magnitude, 1)) / 3)));
    const forcedExponent = preference === "base" ? 0 : preference === "K" ? 1 : preference === "M" ? 2 : preference === "G" ? 3 : preference === "T" ? 4 : automaticExponent;
    const exponent = forcedExponent;
    const prefixes = kind === "count" ? ["", "k", "M", "G", "T"] : ["", "K", "M", "G", "T"];
    const baseUnit = kind === "bitrate" ? "bps" : kind === "rate" ? "pps" : kind === "bytes" ? "B" : "";
    return { kind, divisor: Math.pow(1000, exponent), unit: prefixes[exponent] + baseUnit, prefix: prefixes[exponent], includeZero: kind === "count" };
  }
  return { kind, divisor: 1, unit: unit ?? "", prefix: "", includeZero: false };
}

export function formatMetricValue(value: number | undefined, scale: MetricDisplayScale, fractionDigits = 3, withUnit = true) {
  if (value === undefined || !Number.isFinite(value)) return "-";
  const number = (value / scale.divisor).toLocaleString(activeLocale, { minimumFractionDigits: fractionDigits, maximumFractionDigits: fractionDigits });
  return withUnit && scale.unit ? number + " " + scale.unit : number;
}

export function formatMetricAxisValue(value: number | undefined, scale: MetricDisplayScale, fractionDigits = 3) {
  if (value === undefined || !Number.isFinite(value)) return "-";
  const number = value.toLocaleString(activeLocale, { minimumFractionDigits: fractionDigits, maximumFractionDigits: fractionDigits, useGrouping: false });
  return scale.prefix ? number + " " + scale.prefix : number;
}

export function niceLinearRange(values: readonly number[], includeZero: boolean, targetTicks = 5) {
  const finite = values.filter((value) => Number.isFinite(value));
  let min = finite.length > 0 ? Math.min(...finite) : 0;
  let max = finite.length > 0 ? Math.max(...finite) : 1;
  if (includeZero) { min = Math.min(min, 0); max = Math.max(max, 0); }
  if (min === max) {
    const padding = min === 0 ? 1 : Math.pow(10, Math.floor(Math.log10(Math.abs(min))));
    min -= padding; max += padding;
    if (includeZero) min = Math.min(min, 0);
  }
  const rawStep = (max - min) / Math.max(1, targetTicks - 1);
  const power = Math.pow(10, Math.floor(Math.log10(rawStep)));
  const normalized = rawStep / power;
  const factor = normalized <= 1 ? 1 : normalized <= 2 ? 2 : normalized <= 2.5 ? 2.5 : normalized <= 5 ? 5 : 10;
  const step = factor * power;
  const niceMin = Math.floor(min / step) * step;
  const niceMax = Math.ceil(max / step) * step;
  const splits: number[] = [];
  for (let value = niceMin, count = 0; value <= niceMax + step / 1000000 && count < 32; value += step, count += 1) splits.push(Number(value.toPrecision(12)));
  return { min: niceMin, max: niceMax, splits };
}

function durationScale(unit: string | undefined, magnitude: number): MetricDisplayScale {
  const sourceSeconds = unit === "ms" ? 1e-3 : unit === "us" || unit === "µs" ? 1e-6 : unit === "ns" ? 1e-9 : 1;
  const magnitudeSeconds = magnitude * sourceSeconds;
  const target = magnitudeSeconds >= 1 ? { seconds: 1, unit: "s" } : magnitudeSeconds >= 1e-3 ? { seconds: 1e-3, unit: "ms" } : magnitudeSeconds >= 1e-6 ? { seconds: 1e-6, unit: "µs" } : { seconds: 1e-9, unit: "ns" };
  return { kind: "duration", divisor: target.seconds / sourceSeconds, unit: target.unit, prefix: "", includeZero: false };
}

export function formatBitrate(value?: number) {
  if (value === undefined || !Number.isFinite(value)) return "-";
  const units = ["bps", "Kbps", "Mbps", "Gbps"];
  let current = value;
  let unit = 0;
  while (current >= 1000 && unit < units.length - 1) {
    current /= 1000;
    unit += 1;
  }
  return `${current >= 100 ? current.toFixed(0) : current.toFixed(1)} ${units[unit]}`;
}

export function formatFlowEndpoints(endpointSrc?: string, endpointDst?: string, fallback = "Unknown endpoint") {
  if (endpointSrc && endpointDst) return endpointSrc + " → " + endpointDst;
  return endpointDst ?? endpointSrc ?? fallback;
}

export function formatNumber(value?: number) {
  if (value === undefined || !Number.isFinite(value)) return "-";
  if (Math.abs(value) >= 1000) return value.toLocaleString(activeLocale, { maximumFractionDigits: 1 });
  const fixed = value.toFixed(3).replace(/0+(?![\s\S])/, "");
  return fixed.replace(/[.](?![\s\S])/, "");
}

export function formatFixedNumber(value?: number, fractionDigits = 3) {
  if (value === undefined || !Number.isFinite(value)) return "-";
  return value.toLocaleString(activeLocale, { minimumFractionDigits: fractionDigits, maximumFractionDigits: fractionDigits });
}

export function formatAbsoluteDateTime(epochSec?: number) {
  if (!epochSec) return "Never";
  return new Date(epochSec * 1000).toLocaleString(activeLocale, { year: "numeric", month: "2-digit", day: "2-digit", hour: "2-digit", minute: "2-digit", second: "2-digit", hour12: false });
}

export function formatRelativeTime(epochSec?: number, _locale = "en") {
  if (!epochSec) return "-";
  const diff = Math.max(0, Date.now() / 1000 - epochSec);
  if (diff < 2) return new Intl.RelativeTimeFormat(activeLocale, { numeric: "auto", style: "short" }).format(0, "second");
  if (diff < 60) return new Intl.RelativeTimeFormat(activeLocale, { numeric: "auto", style: "short" }).format(-Math.round(diff), "second");
  return new Date(epochSec * 1000).toLocaleTimeString(activeLocale, { hour12: false });
}
