function alertDetailRows(event: EventLogItem): Array<[string, string]> {
  if (!["alert_detected", "alert_recovered", "alert_data_unavailable", "alert_data_available"].includes(event.type)) return [];
  const detail = eventDetailRecord(event.detail);
  if (!detail) return [];
  const text = (key: string) => detail[key] === undefined || detail[key] === null ? undefined : String(detail[key]);
  const number = (key: string) => typeof detail[key] === "number" ? String(detail[key]) : text(key);
  const duration = (key: string) => {
    const value = detail[key];
    return typeof value === "number" ? `${value} s` : text(key);
  };
  const rows: Array<[string, string | undefined]> = [
    ["Alert rule", text("alert_id")],
    ["Metric", text("metric")],
    ["Current value", number("value")],
    ["Operator", text("comparison_operator") ?? text("operator")],
    ["Trigger threshold", number("error_threshold") ?? number("threshold")],
    ["Recovery threshold", number("recover_threshold")],
    ["Trigger after", duration("trigger_after_sec")],
    ["Recover after", duration("recover_after_sec")],
    ["Missing after", duration("missing_after_sec")],
    ["Severity", text("severity")]
  ];
  return rows.filter((row): row is [string, string] => row[1] !== undefined);
}

