function EventRow({ event, primarySelected, related, measurementAnchorNumber, timeNeighbor, onSelect, onMoveSelection, eventRef, syncTimeOnSelect }: { event: EventLogItem; primarySelected: boolean; related: boolean; measurementAnchorNumber?: number; timeNeighbor: boolean; onSelect: (event: ReactMouseEvent<HTMLButtonElement>) => void; onMoveSelection: (direction: -1 | 1) => void; eventRef: (element: HTMLButtonElement | null) => void; syncTimeOnSelect: boolean }) {
  const timeLabel = formatEventTime(event.time);
  const targetLabel = event.targetLabel ?? event.proto ?? event.scope;
  const onKeyDown = (keyEvent: ReactKeyboardEvent<HTMLButtonElement>) => {
    const direction = keyEvent.key === "ArrowUp" ? -1 : keyEvent.key === "ArrowDown" ? 1 : null;
    if (direction === null) return;
    keyEvent.preventDefault();
    onMoveSelection(direction);
  };
  return (
    <button ref={eventRef} type="button" className={`event-row ${event.level}${primarySelected ? " event-primary-selected" : ""}${related ? " event-related" : ""}${measurementAnchorNumber !== undefined ? " event-measurement-anchor" : ""}${timeNeighbor ? " time-neighbor" : ""}`} onClick={onSelect} onKeyDown={onKeyDown} data-tooltip-key={syncTimeOnSelect ? "tooltip.inspectAndSyncEvent" : "tooltip.inspectEvent"} aria-current={primarySelected ? "true" : undefined} aria-keyshortcuts="ArrowUp ArrowDown">
      <span className="event-marker" aria-label={measurementAnchorNumber === undefined ? undefined : `Measurement anchor ${measurementAnchorNumber}`}>{measurementAnchorNumber === undefined ? "" : `#${measurementAnchorNumber}`}</span>
      <time className="event-time" dateTime={new Date(event.time * 1000).toISOString()} data-tooltip={timeLabel}>{timeLabel}</time>
      <span className="event-level" data-tooltip={event.level}>{event.level}</span>
      <span className="event-target" data-tooltip={targetLabel}>{targetLabel}</span>
      <span className="event-message" data-tooltip={event.message}>{event.message}</span>
