}

function EventMeasurement({ anchors, onClear }: { anchors: MeasurementAnchor[]; onClear: () => void }) {
  const total = anchors.length > 1 ? anchors[anchors.length - 1].event.time - anchors[0].event.time : null;
  return <section className="event-measurement" aria-label="Event time measurement">
    <div className="event-measurement-summary">
      <strong>Measure</strong>
      {total === null ? <span>#{anchors[0].number} · Shift+click another event</span> : <span>#{anchors[0].number} → #{anchors[anchors.length - 1].number} · Δ {formatDuration(total)}</span>}
      <button type="button" onClick={onClear}>Clear</button>
    </div>
    {anchors.length > 1 && <div className="event-measurement-table-wrap">
      <table className="event-measurement-table">
        <caption>Measured intervals between event anchors</caption>
        <thead>
          <tr>
            <th scope="col" rowSpan={2}>From</th>
            <th scope="colgroup" colSpan={6}>From target</th>
            <th scope="col" rowSpan={2}>To</th>
            <th scope="colgroup" colSpan={6}>To target</th>
            <th scope="col" rowSpan={2}>Elapsed</th>
          </tr>
          <tr>
            <MeasurementTargetColumns />
            <MeasurementTargetColumns />
          </tr>
        </thead>
        <tbody>
          {anchors.slice(1).map((anchor, index) => {
            const previous = anchors[index];
            const fromTarget = measurementTargetParts(previous.event);
            const toTarget = measurementTargetParts(anchor.event);
            return <tr key={anchor.event.id} data-tooltip={measurementRowTitle(previous, anchor, fromTarget, toTarget)}>
              <MeasurementAnchorCell anchor={previous} />
              <MeasurementTargetCells target={fromTarget} />
              <MeasurementAnchorCell anchor={anchor} />
              <MeasurementTargetCells target={toTarget} />
              <td className="event-measurement-duration">Δ {formatDuration(anchor.event.time - previous.event.time)}</td>
            </tr>;
          })}
        </tbody>
      </table>
    </div>}
  </section>;
}

function MeasurementTargetColumns() {
  return <>
    <th scope="col" className="event-measurement-target-meta">NIC</th>
    <th scope="col" className="event-measurement-target-meta">VLAN</th>
    <th scope="col" className="event-measurement-target-meta">Proto</th>
    <th scope="col">Src</th>
    <th scope="col" className="event-measurement-target-arrow" aria-label="to">→</th>
    <th scope="col">Dst</th>
  </>;
}

function MeasurementAnchorCell({ anchor }: { anchor: MeasurementAnchor }) {
  const time = formatEventTime(anchor.event.time);
  return <th scope="row" className="event-measurement-anchor-cell">
    <span>#{anchor.number}</span>
    <time dateTime={new Date(anchor.event.time * 1000).toISOString()}>{time.slice(11)}</time>
  </th>;
}
